import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百四十四章 破坏树林","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/244第二百四十四章 破坏树林.md","filePath":"meditation/巴利文大藏经/244第二百四十四章 破坏树林.md"}'),r={name:"meditation/巴利文大藏经/244第二百四十四章 破坏树林.md"};function n(_,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第二百四十四章-破坏树林" tabindex="-1">第二百四十四章 破坏树林 <a class="header-anchor" href="#第二百四十四章-破坏树林" aria-label="Permalink to &quot;第二百四十四章 破坏树林&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>4.非你们的品</p><p>相应部22相应33经/非你们的经(蕴相应/蕴篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！不是你们的东西，不是你们能够永远拥有的东西，你们不要执着和挂念，你们不要对它们生起贪欲、渴爱。只要你们不对这些不属于你们的东西生起贪欲、渴爱，不对你们无法永远拥有的东西生起贪欲、渴爱，不执着和挂念它们，那么你们就能获得功德利益，你们就不会因为它们产生烦恼和痛苦，你们就能够让内心清净安宁。比丘们！什么不是属于你们的东西，什么是你们无法永远拥有的东西？</p><p>比丘们！物质事物、物质身体、感受、念想、行为、认识、分别、判断不是你们的，不是你们能够永远拥有的事物。物质事物、物质身体、感受、念想、行为、认识、分别、判断随时在变化，无法永远的存在，无法永恒的保持不变，不能永远的属于你们，不是你们能够永远拥有的事物。你们不要执着和挂念它们，你们不要对它们生起贪欲、渴爱。只要你们不对这些不属于你们的物质事物、物质身体、感受、念想、行为、认识、分别、判断生起贪欲、渴爱，不对你们无法永远拥有的物质事物、物质身体、感受、念想、行为、认识、分别、判断生起贪欲、渴爱，不执着和挂念它们，那么你们就能获得功德利益，你们就不会因为它们产生烦恼和痛苦，你们就能够让内心清净安宁。</p><p>比丘们！如果有一群人，他们来到深山密林之中，他们随意的割掉野草、砍伐树木、烧掉树林，在深山密林里面想干什么就干什么，对深山密林里面的树木、植被为所欲为、随意破坏，比丘们！你们内心会这样想吗：「这群人割掉了我们的野草，砍伐了我们的树木，烧掉了我们的树林，在我们的树林里面想干什么就干什么，对我们树林里面的树木、植被为所欲为、随意破坏。」比丘们！你们会这样想吗？</p><p>出家弟子们回答：“世尊，我们不会这样的想，因为深山密林里面的这些树木、野草、植被等等的一切根本就不属于我们，不是我们所拥有的东西，既然不是我们所有的东西，这一群人他们割掉野草、砍伐树木、烧掉树林，对树林想干什么就干什么，对树林里面的树木、植被为所欲为、随意破坏，我们都不会在意，我们都不会在乎，我们也不会因为他们的这些行为产生烦恼和痛苦，本来树林里面的树木、野草、植被就不是我们的，他们怎么对待树林都跟我们无关。”</p><p>比丘们！同样的道理，物质事物、物质身体、感受、念想、行为、认识、分别、判断不是你们的，不是你们能够永远拥有的事物。物质事物、物质身体、感受、念想、行为、认识、分别、判断随时在变化，无法永远的存在，无法永恒的保持不变，不能永远的属于你们，不是你们能够永远拥有的事物。你们不要执着和挂念它们，你们不要对它们生起贪欲、渴爱。只要你们不对这些不属于你们的物质事物、物质身体、感受、念想、行为、认识、分别、判断生起贪欲、渴爱，不对你们无法永远拥有的物质事物、物质身体、感受、念想、行为、认识、分别、判断生起贪欲、渴爱，不执着和挂念它们，那么你们就能获得功德利益，你们就不会因为这些事物产生烦恼和痛苦，你们就能够让内心保持长久的清净安宁。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',10)]))}const f=e(r,[["render",n]]);export{m as __pageData,f as default};
